def native_high_quality_camera(label, key):
    """휴대폰 기본 카메라 촬영 결과를 UploadedFile과 유사한 BytesIO로 반환."""
    result = _native_camera_component(label=label, key=key, default=None)
    if not result or not result.get("data_url"):
        return None
    try:
        _, encoded = result["data_url"].split(",", 1)
        image_file = io.BytesIO(base64.b64decode(encoded))
        image_file.name = result.get("name") or "mobile_camera.jpg"
        image_file.type = result.get("mime_type") or "image/jpeg"
        image_file.seek(0)
        return image_file
    except Exception as exc:
        st.error(f"고화질 촬영 사진을 불러오지 못했습니다: {exc}")
        return None

# ============================================================
# 1. 기본 텍스트 정리
# ============================================================

def _clean_text(text):
    """Gemini Markdown 흔적 및 불필요한 문자를 정리"""
    if not text:
        return ""

    text = text.replace("**", "")
    text = text.replace("__", "")
    text = text.replace("###", "")
    text = text.replace("##", "")
    text = text.replace("#", "")
    text = text.replace("---", "")

    return text.strip()


# ============================================================
# 2. Gemini 응답을 6개 섹션으로 분리
# ============================================================

def _parse_report_sections(content):

    sections = {
        "overview": [],
        "risks": [],
        "laws": [],
        "actions": [],
        "cautions": [],
        "opinion": []
    }

    if not content:
        return sections

    # 줄 단위 정리
    lines = [
        line.strip()
        for line in content.splitlines()
        if line.strip()
    ]

    current = None

    for line in lines:

        clean = _clean_text(line)

        # -----------------------------------------
        # 섹션 제목 판별
        # -----------------------------------------

        if re.match(r"^1\.\s*점검\s*개요", clean):
            current = "overview"
            continue

        elif re.match(r"^2\.\s*주요\s*위험요인", clean):
            current = "risks"
            continue

        elif re.match(r"^3\.\s*관련\s*법령\s*및\s*기준", clean):
            current = "laws"
            continue

        elif re.match(r"^4\.\s*권장\s*조치사항", clean):
            current = "actions"
            continue

        elif re.match(r"^5\.\s*현장\s*적용\s*시\s*유의사항", clean):
            current = "cautions"
            continue

        elif re.match(r"^6\.\s*종합\s*의견", clean):
            current = "opinion"
            continue

        # -----------------------------------------
        # 구분선 제거
        # -----------------------------------------

        if set(clean.replace(" ", "")) <= {"=", "-"}:
            continue

        # -----------------------------------------
        # 현재 섹션에 추가
        # -----------------------------------------

        if current:
            sections[current].append(clean)

    return sections


# ============================================================
# 3. 위험요인 파싱
# ============================================================

def _parse_risks(lines):

    risks = []

    for line in lines:

        if line in ["해당 없음", "해당없음"]:
            continue

        # ① 위험요인 | 위험등급: 상 | 위험내용
        parts = [p.strip() for p in line.split("|")]

        if len(parts) >= 2:

            number = ""
            risk_name = ""
            grade = ""
            description = ""

            # 번호 제거
            first = parts[0]

            first = re.sub(
                r"^[①②③④⑤⑥⑦⑧⑨⑩]\s*",
                "",
                first
            )

            first = re.sub(
                r"^\d+[\.\)]\s*",
                "",
                first
            )

            risk_name = first.strip()

            # 위험등급 찾기
            grade_match = re.search(
                r"위험등급\s*[:：]?\s*(상|중|하)",
                line
            )

            if grade_match:
                grade = grade_match.group(1)

            # 위험내용
            if len(parts) >= 3:
                description = parts[-1].strip()

            risks.append({
                "number": len(risks) + 1,
                "name": risk_name,
                "grade": grade if grade else "확인 필요",
                "description": description
            })

        else:

            # 파싱되지 않은 경우에도 내용을 보존
            text = re.sub(
                r"^[①②③④⑤⑥⑦⑧⑨⑩]\s*",
                "",
                line
            )

            risks.append({
                "number": len(risks) + 1,
                "name": text,
                "grade": "확인 필요",
                "description": ""
            })

    return risks


# ============================================================
# 4. 법령 파싱
# ============================================================

def _parse_laws(lines):

    laws = []

    for line in lines:

        if not line:
            continue

        if line in ["해당 없음", "해당없음"]:
            continue

        text = re.sub(
            r"^[①②③④⑤⑥⑦⑧⑨⑩]\s*",
            "",
            line
        )

        text = re.sub(
            r"^\d+[\.\)]\s*",
            "",
            text
        )

        # "/" 기준 분리
        parts = [
            p.strip()
            for p in text.split("/")
        ]

        if len(parts) >= 3:

            law_name = parts[0]
            article = parts[1]
            description = "/".join(parts[2:]).strip()

        elif len(parts) == 2:

            law_name = parts[0]
            article = parts[1]
            description = ""

        else:

            law_name = text
            article = ""
            description = ""

        laws.append({
            "number": len(laws) + 1,
            "law": law_name,
            "article": article,
            "description": description
        })

    return laws


# ============================================================
# 5. 조치사항 파싱
# ============================================================

def _parse_actions(lines):

    actions = []

    for line in lines:

        if not line:
            continue

        text = re.sub(
            r"^[①②③④⑤⑥⑦⑧⑨⑩]\s*",
            "",
            line
        )

        text = re.sub(
            r"^\d+[\.\)]\s*",
            "",
            text
        )

        # "즉시 조치: ..."
        match = re.match(
            r"^(즉시\s*조치|개선\s*조치|예방\s*조치)\s*[:：]\s*(.*)$",
            text
        )

        if match:

            category = match.group(1)
            action = match.group(2).strip()

        else:

            category = "기타 조치"
            action = text

        actions.append({
            "number": len(actions) + 1,
            "category": category,
            "action": action
        })

    return actions


# ============================================================
# 6. 일반 문단 추가
# ============================================================

def _add_normal_paragraph(doc, text):

    text = _clean_text(text)

    if not text:
        return

    p = doc.add_paragraph("")

    p.add_run(
        text,
        font="맑은 고딕",
        size=10
    )


# ============================================================
# 7. 섹션 제목 추가
# ============================================================

def _add_section_title(doc, number, title):

    p = doc.add_paragraph("")

    p.add_run(
        f"{number}. {title}",
        bold=True,
        font="맑은 고딕",
        size=14
    )

    return p


# ============================================================
# 8. 표 셀 입력 함수
# ============================================================

def _set_cell(table, row, col, text, bold=False, size=9):

    text = "" if text is None else str(text)

    cell = table.rows[row].cells[col]

    # 셀 내부에 문단 생성
    p = cell.paragraphs[0]

    p.add_run(
        text,
        bold=bold,
        font="맑은 고딕",
        size=size
    )

    return cell


# ============================================================
# 9. 위험요인 표
# ============================================================

def _add_risk_table(doc, risks):

    if not risks:
        _add_normal_paragraph(
            doc,
            "주요 위험요인이 별도로 확인되지 않았습니다."
        )
        return

    # 헤더 + 데이터
    table = doc.add_table(
        rows=len(risks) + 1,
        cols=4
    )

    headers = [
        "번호",
        "주요 위험요인",
        "위험등급",
        "주요 위험내용"
    ]

    for col, header in enumerate(headers):
        _set_cell(
            table,
            0,
            col,
            header,
            bold=True,
            size=9
        )

    for i, risk in enumerate(risks, start=1):

        _set_cell(
            table,
            i,
            0,
            risk["number"]
        )

        _set_cell(
            table,
            i,
            1,
            risk["name"]
        )

        _set_cell(
            table,
            i,
            2,
            risk["grade"],
            bold=True
        )

        _set_cell(
            table,
            i,
            3,
            risk["description"]
        )

    doc.add_paragraph("")


