# ==========================================
def check_password():
    if st.session_state.get("password_correct", False):
        return True

    logo_html = (
        f'<img src="data:image/png;base64,{img_base64}" alt="한국환경공단 로고">'
        if img_base64 else '<div style="font-size:4rem;">🌱</div>'
    )
    splash_logo_html = (
        f'<img class="keco-splash-logo" src="data:image/png;base64,{img_base64}" alt="한국환경공단 로고">'
        if img_base64 else '<div style="font-size:3.5rem;">🌱</div>'
    )
    # 같은 접속 세션에서 최초 1회만 약 3초간 표시
    if not st.session_state.get("splash_shown", False):
        splash_background = (
            f"url('data:image/webp;base64,{splash_bg_base64}')"
            if splash_bg_base64 else "linear-gradient(160deg, #082C31, #06171D)"
        )
        st.markdown(
            f"""
            <div class="keco-splash" style="--splash-bg:{splash_background};">
                <div class="keco-splash-progress"></div>
            </div>
            """,
            unsafe_allow_html=True,
        )
        st.session_state["splash_shown"] = True

    # 로그인 우측 현장사진: 파일명이 .png 또는 .png.png인 경우 모두 대응
    image_dir = Path(__file__).resolve().parent / "images"
    slide_specs = [
        (["bto.png", "bto.png.png"], "BTO 환경시설사업"),
        (["incineration.png", "incineration.png.png"], "소각시설 설치사업"),
        (["sewage.png", "sewage.png.png"], "공공하수처리시설"),
        (["livestock.png", "livestock.png.png"], "가축분뇨처리시설"),
    ]
    slide_items = []
    for file_candidates, caption in slide_specs:
        image_path = next(
            (image_dir / name for name in file_candidates if (image_dir / name).is_file()),
            None,
        )
        if image_path:
            encoded = base64.b64encode(image_path.read_bytes()).decode("utf-8")
            slide_items.append(
                f'<div class="login-slide">'
                f'<img src="data:image/png;base64,{encoded}" alt="{caption}">'
                f'<div class="login-slide-caption">{caption}</div>'
                f'</div>'
            )

    login_col, photo_col = st.columns([0.92, 1.08], gap="large")

    with login_col:
        st.markdown(
            f"""
            <div class="login-brand-bar">
                {logo_html.replace('<img ', '<img class="login-brand-logo" ')}
                <div class="login-brand-text">
                    <div class="login-brand-name">한국환경공단</div>
                    <div class="login-branch-name">수도권서부환경본부 환경시설관리처</div>
                </div>
            </div>
            <div class="login-page-heading">
                <h1 class="login-page-title">스마트 건설현장<br><span>안전관리 시스템</span></h1>
                <p class="login-page-subtitle">인증된 사내 감독관 전용 서비스입니다.</p>
            </div>
            """,
            unsafe_allow_html=True,
        )

        allowed_users = st.secrets.get("passwords", {})

        with st.form("supervisor_login_form", clear_on_submit=False):
            user_id = st.text_input(
                "감독관 ID(사번)",
                placeholder="사번을 입력하세요",
                key="username_input",
            )
            user_pw = st.text_input(
                "비밀번호",
                type="password",
                placeholder="비밀번호를 입력하세요",
                key="password_input",
            )
            submitted = st.form_submit_button("로그인", width="stretch")

        if submitted:
            user_id_clean = str(user_id).strip()
            user_pw_clean = str(user_pw).strip()
            allowed_users_str = {str(k): str(v) for k, v in allowed_users.items()}

            if not user_id_clean or not user_pw_clean:
                st.warning("사번과 비밀번호를 모두 입력해 주세요.")
            elif (
                user_id_clean in allowed_users_str
                and allowed_users_str[user_id_clean] == user_pw_clean
            ):
                st.session_state["password_correct"] = True
                st.session_state["logged_user"] = user_id_clean
                st.rerun()
            else:
                st.error("아이디 또는 비밀번호가 올바르지 않습니다.")

    with photo_col:
        if slide_items:
            st.markdown(
                f'<div class="login-photo-panel">{"".join(slide_items)}</div>',
                unsafe_allow_html=True,
            )
        else:
            st.markdown(
                """
                <div class="login-photo-panel" style="display:flex;align-items:center;justify-content:center;">
                    <div style="text-align:center;color:#52645C;padding:24px;">
                        <div style="font-size:3rem;margin-bottom:12px;">🌿</div>
                        환경시설 현장사진
                    </div>
                </div>
                """,
                unsafe_allow_html=True,
            )

    return False


